<?php declare(strict_types=1); namespace Tests\Unit\Arena; use App\Domain\Arena\Service\DuelScoring; use PHPUnit\Framework\TestCase; final class DuelScoringTest extends TestCase { public function testScoresCorrectAnswersByServerOrderAndPenalizesWrong():void{$at=new \DateTimeImmutable('2026-01-01T00:00:00.000000Z');$scores=(new DuelScoring())->score([['userId'=>'c','correct'=>true,'receivedAt'=>$at->modify('+3 microseconds'),'id'=>'c'],['userId'=>'a','correct'=>true,'receivedAt'=>$at,'id'=>'a'],['userId'=>'x','correct'=>false,'receivedAt'=>$at->modify('+1 microseconds'),'id'=>'x'],['userId'=>'b','correct'=>true,'receivedAt'=>$at->modify('+2 microseconds'),'id'=>'b'],['userId'=>'d','correct'=>true,'receivedAt'=>$at->modify('+4 microseconds'),'id'=>'d']]);self::assertSame(['points'=>100,'correctRank'=>1],$scores['a']);self::assertSame(['points'=>75,'correctRank'=>2],$scores['b']);self::assertSame(['points'=>50,'correctRank'=>3],$scores['c']);self::assertSame(['points'=>25,'correctRank'=>4],$scores['d']);self::assertSame(['points'=>-25,'correctRank'=>null],$scores['x']);} }
